import { Effect } from "effect"

export interface Receipt {
  readonly orderId: string
  readonly totalCents: number
  readonly currency: string
}

export const deliverReceipt = (endpoint: string, receipt: Receipt) =>
  Effect.scoped(
    Effect.gen(function*() {
      const signal = yield* Effect.abortSignal

      const response = yield* Effect.tryPromise({
        try: () =>
          fetch(endpoint, {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify(receipt),
            signal
          }),
        catch: (cause) => new Error("Receipt webhook request failed", { cause })
      })

      if (!response.ok) {
        return yield* Effect.fail(
          new Error(`Receipt webhook returned ${response.status}`)
        )
      }

      const acknowledgement = yield* Effect.tryPromise({
        try: () => response.text(),
        catch: (cause) => new Error("Could not read acknowledgement", { cause })
      })

      return { orderId: receipt.orderId, acknowledgement }
    })
  ).pipe(Effect.timeout("8 seconds"))
